def gen(rng):
    def fmt(a):
        return str(len(a)) + '\n' + ' '.join(map(str, a))
    tests = [fmt([1]), fmt([10**9]), fmt([3, 3]), fmt([1, 2]), fmt([2, 7, 4, 1, 8, 1]),
             fmt([5, 5, 8, 8]), fmt([7, 7, 7]), fmt([1, 1, 1, 1, 1])]
    for n in (2, 3, 4, 6, 8, 10, 15, 20, 30):
        for hi in (5, 100):
            tests.append(fmt([rng.randint(1, hi) for _ in range(n)]))
    N = 100000
    tests.append(fmt([rng.randint(1, 10**9) for _ in range(N)]))
    tests.append(fmt([1] * N))
    tests.append(fmt([rng.randint(1, 10) for _ in range(N)]))
    tests.append(fmt([10**9 - i for i in range(N)]))
    return tests
